import{_ as t,o as e,c as r,a2 as l}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"裸机云密码修改与重置指南","description":"","frontmatter":{"title":"裸机云密码修改与重置指南"},"headers":[],"relativePath":"ops-knowledge-base/baremetal/password-change-reset-guide.md","filePath":"ops-knowledge-base/baremetal/password-change-reset-guide.md","lastUpdated":1788259091000}'),i={name:"ops-knowledge-base/baremetal/password-change-reset-guide.md"};function o(n,a,s,h,d,p){return e(),r("div",null,[...a[0]||(a[0]=[l('<h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>本文档介绍裸机云服务器密码修改及密码重置的操作方法，适用于 Linux 和 Windows 系统，帮助客户在忘记密码或需要修改密码时快速完成操作。</p><p><strong>适用产品：</strong> 裸机云（Bare Metal Cloud）</p><hr><h2 id="一、修改密码与重置密码的区别" tabindex="-1">一、修改密码与重置密码的区别 <a class="header-anchor" href="#一、修改密码与重置密码的区别" aria-label="Permalink to &quot;一、修改密码与重置密码的区别&quot;">​</a></h2><p>在操作前，请先确认您的需求。</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>操作</strong></td><td><strong>适用场景</strong></td></tr><tr><td>修改密码</td><td>当前可以正常登录服务器，希望更换新的登录密码。</td></tr><tr><td>重置密码</td><td>已忘记服务器密码，无法登录系统，需要重新生成新的登录密码。</td></tr></tbody></table><h2 id="二、修改系统密码" tabindex="-1">二、修改系统密码 <a class="header-anchor" href="#二、修改系统密码" aria-label="Permalink to &quot;二、修改系统密码&quot;">​</a></h2><p>如果当前可以正常登录服务器，建议直接在系统内修改密码。</p><h3 id="linux-系统" tabindex="-1">Linux 系统 <a class="header-anchor" href="#linux-系统" aria-label="Permalink to &quot;Linux 系统&quot;">​</a></h3><p>适用于：</p><ul><li>可以通过 SSH 登录服务器；</li><li>可以通过 VNC 登录服务器。</li></ul><p>修改完成后，请使用新的密码重新登录进行验证。</p><hr><h3 id="windows-系统" tabindex="-1">Windows 系统 <a class="header-anchor" href="#windows-系统" aria-label="Permalink to &quot;Windows 系统&quot;">​</a></h3><p>适用于：</p><ul><li>可以通过远程桌面（RDP）登录服务器；</li><li>可以通过 VNC 登录服务器。</li></ul><p>修改完成后，请重新登录系统验证新密码是否生效。</p><blockquote><p><strong>说明：</strong> 不同操作系统版本修改密码的方式可能略有不同，请根据实际系统进行操作。</p></blockquote><hr><h2 id="三、通过控制台重置密码" tabindex="-1">三、通过控制台重置密码 <a class="header-anchor" href="#三、通过控制台重置密码" aria-label="Permalink to &quot;三、通过控制台重置密码&quot;">​</a></h2><p>当忘记服务器密码，无法正常登录时，可通过裸机云控制台的<strong>重置密码</strong>功能重新生成登录密码。</p><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><ol><li>登录 Raksmart 客户后台。</li><li>进入 <strong>产品管理</strong> → <strong>裸机云</strong>。</li><li>选择需要管理的服务器。</li><li>点击进入 <strong>管理</strong> 页面。</li><li>点击 <strong>重置密码</strong>。</li><li>系统将自动随机生成一个新的登录密码。</li><li>如需更换，可点击 <strong>重新生成</strong>（随机生成）按钮，获取新的随机密码。</li><li>确认后，可点击 <strong>复制</strong> 按钮保存新的密码。</li></ol><hr><h2 id="重置完成后" tabindex="-1">重置完成后 <a class="header-anchor" href="#重置完成后" aria-label="Permalink to &quot;重置完成后&quot;">​</a></h2><p>密码生成完成后，可直接使用新的密码登录服务器。</p><p>支持通过以下方式登录：</p><ul><li>Linux：SSH 或 VNC</li><li>Windows：远程桌面（RDP）或 VNC</li></ul><blockquote><p><strong>说明：</strong></p><p>密码重置完成后<strong>无需重启服务器</strong>，新密码会立即生效。</p></blockquote><hr><h2 id="四、什么时候建议使用-vnc" tabindex="-1">四、什么时候建议使用 VNC <a class="header-anchor" href="#四、什么时候建议使用-vnc" aria-label="Permalink to &quot;四、什么时候建议使用 VNC&quot;">​</a></h2><p>如果出现以下情况，建议使用 VNC 登录服务器进行检查：</p><ul><li>SSH 无法连接；</li><li>RDP 无法连接；</li><li>无法确认服务器是否正常启动；</li><li>网络配置异常；</li><li>需要查看系统启动过程。</li></ul><blockquote><p><strong>说明：</strong></p><p>VNC 为服务器控制台连接，即使网络连接异常，通常仍可进入系统进行管理。</p></blockquote><p>详细操作请参考：《裸机云 VNC 控制台使用指南》。</p><hr><h2 id="五、密码安全建议" tabindex="-1">五、密码安全建议 <a class="header-anchor" href="#五、密码安全建议" aria-label="Permalink to &quot;五、密码安全建议&quot;">​</a></h2><p>为了提高服务器安全性，建议：</p><ul><li>密码长度不少于 12 位；</li><li>同时包含大小写字母、数字及特殊字符；</li><li>不使用生日、手机号等容易猜测的信息；</li><li>定期修改密码；</li><li>妥善保管登录密码，避免泄露。</li></ul><hr><h2 id="六、常见问题" tabindex="-1">六、常见问题 <a class="header-anchor" href="#六、常见问题" aria-label="Permalink to &quot;六、常见问题&quot;">​</a></h2><h3 id="q1-修改密码会影响服务器中的数据吗" tabindex="-1">Q1：修改密码会影响服务器中的数据吗？ <a class="header-anchor" href="#q1-修改密码会影响服务器中的数据吗" aria-label="Permalink to &quot;Q1：修改密码会影响服务器中的数据吗？&quot;">​</a></h3><p>不会。</p><p>修改或重置密码仅影响登录凭据，不会影响服务器中的系统、应用程序或业务数据。</p><hr><h3 id="q2-重置密码后需要重启服务器吗" tabindex="-1">Q2：重置密码后需要重启服务器吗？ <a class="header-anchor" href="#q2-重置密码后需要重启服务器吗" aria-label="Permalink to &quot;Q2：重置密码后需要重启服务器吗？&quot;">​</a></h3><p>不需要。</p><p>通过控制台重置密码后，新密码会立即生效，无需重启服务器。</p><hr><h3 id="q3-重置密码后为什么还是无法登录" tabindex="-1">Q3：重置密码后为什么还是无法登录？ <a class="header-anchor" href="#q3-重置密码后为什么还是无法登录" aria-label="Permalink to &quot;Q3：重置密码后为什么还是无法登录？&quot;">​</a></h3><p>请确认以下内容：</p><ul><li>是否使用了最新生成的密码；</li><li>登录用户名是否正确（如 Linux 默认使用 <strong>root</strong>，Windows 默认使用 <strong>Administrator</strong>）；</li><li>是否连接到了正确的 IP 地址及端口；</li><li>SSH 或 RDP 服务是否正常运行；</li><li>安全组或系统防火墙是否限制了连接。</li></ul><p>如仍无法登录，可尝试使用 VNC 控制台进入系统进行检查。</p><hr><h3 id="q4-可以自己设置重置后的密码吗" tabindex="-1">Q4：可以自己设置重置后的密码吗？ <a class="header-anchor" href="#q4-可以自己设置重置后的密码吗" aria-label="Permalink to &quot;Q4：可以自己设置重置后的密码吗？&quot;">​</a></h3><p>可以，</p><p>控制台重置密码功能有<strong>随机生成密码</strong>的方式，也可以输入自己设置的密码进行重置。</p><hr><h3 id="q5-重置密码会导致服务器重启吗" tabindex="-1">Q5：重置密码会导致服务器重启吗？ <a class="header-anchor" href="#q5-重置密码会导致服务器重启吗" aria-label="Permalink to &quot;Q5：重置密码会导致服务器重启吗？&quot;">​</a></h3><p>不会。</p><p>控制台重置密码不会影响服务器当前运行状态，也不会导致服务器自动重启。</p><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>⚠️ 建议首次登录服务器后立即修改默认密码。</p><p>⚠️ 重置密码前，请先复制或记录新的随机密码，避免关闭页面后忘记密码。</p><p>⚠️ 如果服务器已部署自动化运维工具，请同步更新相关密码配置，以免任务执行失败。</p><p>⚠️ 如长时间无法使用新密码登录，请优先通过 VNC 登录服务器确认系统状态。</p><hr>',69)])])}const b=t(i,[["render",o]]);export{c as __pageData,b as default};
